const NMX={"en": ["Monthly", "Alliance", "Eternal"], "es": ["Mensual", "Alianza", "Eterna"], "pt": ["Mensal", "Aliança", "Eterna"], "it": ["Mensile", "Alleanza", "Eterna"], "de": ["Monatlich", "Bund", "Ewig"], "ar": ["شهري", "العهد", "الأبدية"], "zh": ["月度", "盟约", "永恒"], "nl": ["Maandelijks", "Verbond", "Eeuwig"], "ru": ["Ежемесячно", "Союз", "Вечный"], "ln": ["Sanza na sanza", "Bondeko", "Seko"], "sw": ["Kila mwezi", "Agano", "Milele"], "hi": ["मासिक", "वाचा", "अनन्त"], "id": ["Bulanan", "Perjanjian", "Kekal"], "tl": ["Buwanan", "Tipan", "Walang hanggan"], "ko": ["월간", "언약", "영원"], "vi": ["Hằng tháng", "Giao ước", "Vĩnh cửu"], "pl": ["Miesięczny", "Przymierze", "Wieczny"], "uk": ["Щомісяця", "Завіт", "Вічний"], "ur": ["ماہانہ", "عہد", "ابدی"], "ro": ["Lunar", "Legământ", "Veșnic"]};
function PLN(n){const i={"Mensuel":0,"Alliance":1,"Éternelle":2}[n];if(i===undefined)return n;const a=NMX[String(typeof LANG!=="undefined"?LANG:"fr").toLowerCase()];return a?a[i]:n;}
function getPlanName(){ if(window.NLJ_PLANNAME&&/^(Mensuel|Alliance|Éternelle)$/.test(window.NLJ_PLANNAME))return window.NLJ_PLANNAME; const names=["","Mensuel","Alliance","Éternelle"]; return names[NLJ_PLAN]||"Alliance"; }

function applyLang(code){
  LANG=code;
  try{ localStorage.setItem('niamke_lang',String(code).toLowerCase()); }catch(e){}
  document.documentElement.lang = code.toLowerCase();
  if(code==='AR'||code==='UR'){ document.documentElement.dir='rtl'; document.body.style.direction='rtl'; }
  else { document.documentElement.dir='ltr'; document.body.style.direction='ltr'; }
  const t=Object.assign({},TR.FR,TR[LANG]);
  // 1. Traduire tous les éléments statiques marqués data-i18n
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key=el.getAttribute('data-i18n');
    if(t[key]) el.textContent=t[key];
  });
  // 2. Placeholders
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{
    const key=el.getAttribute('data-i18n-ph');
    if(t[key]) el.placeholder=t[key];
  });
  // 3. Rerender dynamique complet
  if(window.nljFilterLab)nljFilterLab();
  renderPlan();
  renderPrayer();
  if(musicVisible){ renderMusicList(); }
  // 4. Bouton principal download quand fermé
  const txtEl=document.getElementById('dlText');
  if(txtEl && !musicVisible) txtEl.textContent=t.dl_btn;
  const icon=document.getElementById('dlIcon');
  // 5. Titre page
  document.title = t.nav_premium + " — Niamké Love Jésus";
  // 6. Sync select
  const sel=document.getElementById('langSelect');
  if(sel && sel.value!==code) sel.value=code;
}

function renderPlan(){
 const t=Object.assign({},TR.FR,TR[LANG]);
 const benefits=[
  {t:t.likes_full,d:t.likes_desc,lv:1,ok:true},
  {t:t.chat_full,d:t.chat_desc,lv:1,ok:true},
  {t:t.study_full,d:t.study_desc,lv:1,ok:true},
  {t:t.support_full,d:t.support_desc,lv:1,ok:true},
  {t:t.game_full,d:t.game_desc,lv:1,ok:NLJ_PLAN>=1},
  {t:t.filter_full,d:t.filter_desc,lv:1,ok:NLJ_PLAN>=1},
  {t:t.star_full,d:t.star_desc,lv:2,ok:NLJ_PLAN>=2},
  {t:t.shield_full,d:t.shield_desc,lv:2,ok:NLJ_PLAN>=2},
  {t:t.gem_full,d:t.gem_desc,lv:2,ok:NLJ_PLAN>=2},
  {t:t.crown_full,d:t.crown_desc,lv:3,ok:NLJ_PLAN>=3}
 ];
 const total=benefits.length; const unlocked=benefits.filter(b=>b.ok).length;
 const planEl=document.getElementById('planCard');
 if(!planEl) return;
 const NM=["",PLN("Mensuel"),PLN("Alliance"),PLN("Éternelle")];
  const bd=document.getElementById('planBadge'); if(bd) bd.textContent=bd.textContent.replace(/alliance/i,PLN(getPlanName()).toUpperCase());
  const pct=Math.round(unlocked/total*100);
  planEl.innerHTML='<div class="plan-box"><div class="ring" style="--p:'+pct+'"><span>'+unlocked+'/'+total+'</span></div><div><div class="plan-sub">'+escapeHTML(t.plan_title)+'</div><div class="plan-name">'+escapeHTML(PLN(getPlanName()))+'</div><div class="plan-sub">'+unlocked+' '+escapeHTML(t.plan_unlocked)+' '+total+' '+escapeHTML(t.plan_unlocked2)+'</div><a href="https://wa.me/'+WA+'" target="_blank" rel="noopener noreferrer" class="btn btn-gold btn-sm" style="margin-top:12px">WhatsApp</a></div></div>';
  const grid=document.getElementById('advantagesGrid');
  if(grid) grid.innerHTML=[1,2,3].map(lv=>{const on=NLJ_PLAN>=lv,nm=NM[lv];return '<div class="tier"><div class="tier-h"><b>'+nm+'</b><span class="tier-tag '+(on?'on':'off')+'">'+(on?'✅ '+escapeHTML(t.included):'🔒 '+escapeHTML(t.with_plan)+' '+nm)+'</span></div><div class="grid-3">'+benefits.filter(b=>b.lv===lv).map(b=>'<div class="perk '+(b.ok?'on':'off')+'"><div class="perk-t">'+(b.ok?'✅ ':'🔒 ')+escapeHTML(b.t)+'</div><p>'+escapeHTML(b.d)+'</p></div>').join('')+'</div></div>';}).join('');
}
let DBMUSIC=null;
const MUSIC_PATH_KEY=/^(storage_path|file_path|path|file|file_url|audio_url|audio|url)$/i;
function musicSb(){try{return window.parent.supabaseClient;}catch(e){return null;}}
async function loadDbMusic(){
 try{
  const c=musicSb(); if(!c) return;
  const r=await c.from('musiques').select('*').order('created_at',{ascending:false}).limit(200);
  if(r.error||!r.data||!r.data.length) return;
  DBMUSIC=r.data.map(function(x){const pk=Object.keys(x).find(function(k){return MUSIC_PATH_KEY.test(k)&&x[k];});return {t:x.title||x.titre||x.name||'Musique',dur:x.artist||'',size:'',path:pk?x[pk]:null};}).filter(function(x){return x.path&&!(window.NLJ_EMBED&&(NLJ_EMBED.isLink||NLJ_EMBED.parse)(x.path));});
  if(DBMUSIC.length&&musicVisible) renderMusicList();
 }catch(e){}
}
function getMusicTitles(){
 const t=Object.assign({},TR.FR,TR[LANG]);
 if(DBMUSIC&&DBMUSIC.length) return DBMUSIC;
 return [{t:t.music1,dur:"4:12",size:"9.8 Mo"},{t:t.music2,dur:"5:03",size:"11.2 Mo"},{t:t.music3,dur:"3:45",size:"8.5 Mo"},{t:t.music4,dur:"4:30",size:"10.1 Mo"},{t:t.music5,dur:"3:58",size:"9.0 Mo"},{t:t.music6,dur:"4:15",size:"9.6 Mo"}];
}
let musicVisible=false;
function renderMusicList(){
 const t=Object.assign({},TR.FR,TR[LANG]);
 const list=document.getElementById('musicList');
 if(!list) return;
 const MUSIC=getMusicTitles();
 list.innerHTML=MUSIC.map((m,i)=>'<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 6px;border-bottom:1px solid #fef3c7"><div><strong style="font-size:.9rem">'+escapeHTML(m.t)+'</strong><br><small style="color:var(--muted)">'+m.dur+'</small></div><button class="btn btn-gold btn-sm" data-nlj-act="downloadOne" data-nlj-a="['+i+']">📥</button></div>').join('')+'<div style="margin-top:10px;display:flex;gap:8px"><button class="btn btn-gold" style="flex:1" data-nlj-act="downloadAll">'+escapeHTML(t.all_zip||"Download ZIP")+'</button><button class="btn btn-outline btn-sm" data-nlj-act="downloadMusic">'+escapeHTML(t.close||"Close")+'</button></div>';
}
function downloadMusic(){
 const t=Object.assign({},TR.FR,TR[LANG]);
 const txtEl=document.getElementById('dlText');
 const icon=document.getElementById('dlIcon');
 const list=document.getElementById('musicList');
 if(!musicVisible){ list.style.display='block'; renderMusicList(); loadDbMusic(); if(txtEl) txtEl.textContent=t.close_list; if(icon) icon.textContent='🎵'; musicVisible=true; showToast(t.available); }
 else { list.style.display='none'; if(txtEl) txtEl.textContent=t.dl_btn; if(icon) icon.textContent='📥'; musicVisible=false; }
}
async function downloadOne(i){const m=getMusicTitles()[i];
 if(m&&m.path){
  try{
   let url=m.path;
   if(!/^https?:/i.test(url)){const c=musicSb(); const r=await c.storage.from('musiques').createSignedUrl(m.path,3600,{download:true}); if(r.error) throw r.error; url=r.data.signedUrl;}
   const a=document.createElement('a'); a.href=url; a.download=''; document.body.appendChild(a); a.click(); a.remove(); return;
  }catch(e){ showToast('Téléchargement impossible : '+(e.message||e)); return; }
 }
 window.open("https://wa.me/"+WA+"?text="+encodeURIComponent("Bonjour Niamké Love Jésus - Je souhaite recevoir le chant : "+m.t+" - Plan: "+getPlanName()),"_blank");}
function downloadAll(){ const t=Object.assign({},TR.FR,TR[LANG]); showToast(t.zip_prep); const msg="Bonjour Niamké Love Jésus - Je veux telecharger ma collection Premium - Plan: "+getPlanName()+" - Langue: "+LANG; window.open("https://wa.me/"+WA+"?text="+encodeURIComponent(msg),'_blank'); }
function goTo(id){if(id==='rencontre') parent.postMessage({nlj:'go',page:'p2',id:'rencontre'},'*'); if(id==='etude') document.getElementById('etude').scrollIntoView({behavior:'smooth'});}
function contactWA(type){const t=Object.assign({},TR.FR,TR[LANG]); const msgs={support:t.support_btn,verif:t.verif_btn,coach:t.coach_btn}; window.open("https://wa.me/"+WA+"?text="+encodeURIComponent("Bonjour, "+(msgs[type]||type)+" - Plan: "+getPlanName()),'_blank');}
let prayers=[]; try{prayers=JSON.parse(localStorage.getItem('nlj_prayers')||'[]');}catch(e){}
function savePrayers(a){if(JSON.stringify(a).length>4000000){showToast("Carnet plein"); return;} prayers=a; try{localStorage.setItem('nlj_prayers',JSON.stringify(a));}catch(e){} renderPrayer();}
function renderPrayer(){ const t=Object.assign({},TR.FR,TR[LANG]); const el=document.getElementById('prayerList'); if(!el) return; el.innerHTML=prayers.length===0?'<p style="color:var(--muted);font-size:.9rem">'+escapeHTML(t.no_prayer)+'</p>':prayers.map(x=>'<div style="display:flex;gap:8px;align-items:center;padding:8px 10px;border:1px solid var(--border);border-radius:10px;background:'+(x.done?'#f0fdf4':'#fff')+'"><input type="checkbox" '+(x.done?'checked':'')+' data-nlj-chg="togglePrayer" data-nlj-a="['+(+x.id||0)+']"><span style="flex:1;font-size:.92rem;'+(x.done?'text-decoration:line-through;color:var(--muted)':'')+'">'+escapeHTML(x.t)+'</span><button data-nlj-act="deletePrayer" data-nlj-a="['+(+x.id||0)+']" style="background:transparent;border:none;cursor:pointer;color:#94a3b8">✕</button></div>').join(''); }
function addPrayer(){const inp=document.getElementById('prayerInput'); const v=inp.value.trim(); if(!v) return; savePrayers(prayers.concat([{id:Date.now(),t:v,done:false}])); inp.value='';}
function togglePrayer(id){savePrayers(prayers.map(p=>p.id===id?{...p,done:!p.done}:p));}
function deletePrayer(id){savePrayers(prayers.filter(p=>p.id!==id));}
document.getElementById('prayerInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)) addPrayer();});
function initApp(){
  const sel=document.getElementById('langSelect');
  if(sel){ sel.addEventListener('change', (e)=>{ applyLang(e.target.value); }); }
  let savedLang='FR'; try{savedLang=(localStorage.getItem('niamke_lang')||'fr').toUpperCase();}catch(e){}
  if(sel) sel.value=savedLang;
  try{ applyLang((TR[savedLang]||['LN','SW','HI','ID','TL','KO','VI','PL','UK','UR','RO'].indexOf(savedLang)>=0)?savedLang:'FR'); }catch(err){ console.error(err); applyLang('FR'); }
}
if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', initApp); } else { initApp(); }
